package com.hms.billing;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/subscription/invoices") public class InvoiceController {private final TenantRepository tenants;private final SubscriptionInvoiceRepository invoices;public InvoiceController(TenantRepository t,SubscriptionInvoiceRepository i){tenants=t;invoices=i;} @GetMapping public List<SubscriptionInvoice> list(@PathVariable String tenantSlug){return invoices.findAllByTenantIdOrderByIssuedOnDesc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public SubscriptionInvoice create(@PathVariable String tenantSlug,@Valid @RequestBody CreateInvoiceRequest r){if(r.dueOn().isBefore(r.issuedOn()))throw new IllegalArgumentException("Invoice due date cannot be before issue date");return invoices.save(new SubscriptionInvoice(tenant(tenantSlug),r));} @PatchMapping("/{invoiceId}/status") public SubscriptionInvoice status(@PathVariable String tenantSlug,@PathVariable UUID invoiceId,@Valid @RequestBody InvoiceStatusRequest r){SubscriptionInvoice invoice=invoices.findByIdAndTenantId(invoiceId,tenant(tenantSlug)).orElseThrow(()->new IllegalArgumentException("Invoice not found"));switch(r.status()){case PAID->invoice.markPaid();case PAST_DUE->invoice.markPastDue(r.failureReason());case VOID->invoice.voidInvoice();case OPEN->throw new IllegalArgumentException("An invoice cannot be reopened");}return invoices.save(invoice);} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
